import React from "react";

/**
 * Product emblem - a correctly proportioned mini UAE flag (red vertical hoist at
 * 1/4 width, then green / white / black horizontal stripes), rounded.
 * Built with plain divs so it always renders (no SVG clip-path quirks).
 */
const BrandMark: React.FC<{ size?: number }> = ({ size = 30 }) => {
  const h = Math.round(size * 0.68);
  const r = Math.max(3, Math.round(size * 0.14));
  return (
    <span
      role="img"
      aria-label="United Arab Emirates"
      style={{
        display: "inline-block",
        width: size,
        height: h,
        flex: "none",
        borderRadius: r,
        overflow: "hidden",
        boxShadow: "0 0 0 1px rgba(255,255,255,0.18)",
      }}
    >
      <span style={{ display: "flex", width: "100%", height: "100%" }}>
        <span style={{ width: "25%", background: "#ef3340" }} />
        <span style={{ flex: 1, display: "flex", flexDirection: "column" }}>
          <span style={{ flex: 1, background: "#00843d" }} />
          <span style={{ flex: 1, background: "#ffffff" }} />
          <span style={{ flex: 1, background: "#0b0b0c" }} />
        </span>
      </span>
    </span>
  );
};

export default BrandMark;
