/**
 * Live Dubai conditions from keyless Open-Meteo (REAL data). Fails gracefully:
 * on any error every field is null and `ok` is false, so the UI shows "-".
 */
export interface Conditions {
  tempC: number | null;
  humidity: number | null;
  pm10: number | null;
  dust: number | null;
  ok: boolean;
}

const DUBAI = { lat: 25.2048, lon: 55.2708 };
const EMPTY: Conditions = { tempC: null, humidity: null, pm10: null, dust: null, ok: false };

export const fetchConditions = async (): Promise<Conditions> => {
  try {
    const [w, a] = await Promise.all([
      fetch(
        `https://api.open-meteo.com/v1/forecast?latitude=${DUBAI.lat}&longitude=${DUBAI.lon}&current=temperature_2m,relative_humidity_2m`,
      ).then((r) => r.json()),
      fetch(
        `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${DUBAI.lat}&longitude=${DUBAI.lon}&current=pm10,dust`,
      ).then((r) => r.json()),
    ]);
    const temp = w && w.current ? w.current.temperature_2m : null;
    const hum = w && w.current ? w.current.relative_humidity_2m : null;
    const pm10 = a && a.current ? a.current.pm10 : null;
    const dust = a && a.current ? a.current.dust : null;
    return {
      tempC: typeof temp === "number" ? temp : null,
      humidity: typeof hum === "number" ? hum : null,
      pm10: typeof pm10 === "number" ? pm10 : null,
      dust: typeof dust === "number" ? dust : null,
      ok: true,
    };
  } catch {
    return EMPTY;
  }
};
