/**
 * MODELLED action nudges derived from the forecast. Rule-based: each nudge pairs
 * a triggering signal with a recommended action for a specific facility and time
 * window. Hospital load is always expressed as "projected respiratory demand vs
 * normal", never as claimed real occupancy.
 */
import { SITES } from "../data/demo/sites";
import { nodeRiskAt, cityRiskIndex, RISK_TIER_MAP } from "./forecast";

export type Severity = "high" | "medium" | "low";

export interface Nudge {
  id: string;
  severity: Severity;
  icon: string;
  targetId: string;
  target: string;
  targetAr: string;
  day: number;
  signal: string;
  signalAr: string;
  action: string;
  actionAr: string;
}

const ELEVATED = RISK_TIER_MAP.elevated.min;
const MODERATE = RISK_TIER_MAP.moderate.min;
const SEV_RANK: Record<Severity, number> = { high: 0, medium: 1, low: 2 };

/** Projected respiratory-demand increase over the next 5 days, in %. */
export const projectedDemandIncrease = (day: number): number => {
  const future = Math.min(14, day + 5);
  const base = Math.max(8, cityRiskIndex(day));
  return Math.round((cityRiskIndex(future) / base - 1) * 100);
};

export const nudgesFor = (day: number): Nudge[] => {
  const out: Nudge[] = [];
  const demand = projectedDemandIncrease(day);
  const future = Math.min(14, day + 5);

  if (demand >= 30) {
    SITES.filter((s) => s.type === "hospital").forEach((h) =>
      out.push({
        id: `hosp-${h.id}`,
        severity: "high",
        icon: "hospital",
        targetId: h.id,
        target: h.name,
        targetAr: h.nameAr,
        day: future,
        signal: `Projected respiratory demand +${demand}% within 5 days`,
        signalAr: `طلب تنفسي متوقع +${demand}٪ خلال ٥ أيام`,
        action: "Pre-position staff, beds, oxygen and antivirals",
        actionAr: "تجهيز الكوادر والأسرّة والأكسجين ومضادات الفيروسات مسبقاً",
      }),
    );
  }

  SITES.forEach((s) => {
    const r = nodeRiskAt(s.id, day);
    if (s.type === "gateway" && r >= MODERATE) {
      out.push({
        id: `air-${s.id}`,
        severity: r >= ELEVATED ? "high" : "medium",
        icon: "gateway",
        targetId: s.id,
        target: s.name,
        targetAr: s.nameAr,
        day,
        signal: "Arrivals risk elevated",
        signalAr: "ارتفاع خطر الوافدين",
        action: "Activate cough-screening lanes at arrivals",
        actionAr: "تفعيل مسارات فحص السعال عند الوصول",
      });
    }
    if (s.type === "pharmacy" && (r >= MODERATE || demand >= 20)) {
      out.push({
        id: `ph-${s.id}`,
        severity: "medium",
        icon: "pharmacy",
        targetId: s.id,
        target: s.name,
        targetAr: s.nameAr,
        day,
        signal: "Projected surge in respiratory visits",
        signalAr: "ارتفاع متوقع في الزيارات التنفسية",
        action: "Restock masks, antipyretics and antivirals",
        actionAr: "إعادة تخزين الكمامات وخافضات الحرارة ومضادات الفيروسات",
      });
    }
    if (s.type === "mall" && r >= ELEVATED) {
      out.push({
        id: `venue-${s.id}`,
        severity: "medium",
        icon: "mall",
        targetId: s.id,
        target: s.name,
        targetAr: s.nameAr,
        day,
        signal: "High crowd density and risk",
        signalAr: "كثافة بشرية وخطر مرتفع",
        action: "Deploy hygiene crews, sanitiser points and mask advisory",
        actionAr: "نشر فرق النظافة ونقاط التعقيم وإرشادات الكمامات",
      });
    }
    if (s.type === "education" && r >= MODERATE) {
      out.push({
        id: `edu-${s.id}`,
        severity: "low",
        icon: "education",
        targetId: s.id,
        target: s.name,
        targetAr: s.nameAr,
        day,
        signal: "District respiratory risk rising",
        signalAr: "ارتفاع الخطر التنفسي في المنطقة",
        action: "Hygiene campaign and self-screening reminder",
        actionAr: "حملة نظافة وتذكير بالفحص الذاتي",
      });
    }
  });

  return out.sort((a, b) => SEV_RANK[a.severity] - SEV_RANK[b.severity]).slice(0, 8);
};
