import React from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { topHotspots, RISK_TIER_MAP, Hotspot, INDEX_SCALE, nodeRiskAt } from "../../model/forecast";

const List = styled.div`
  display: flex;
  flex-direction: column;
`;
const Row = styled.button`
  display: flex;
  align-items: center;
  gap: 11px;
  text-align: start;
  width: 100%;
  background: transparent;
  border: 0;
  border-top: 1px solid var(--border);
  padding: 10px 2px;
  cursor: pointer;
  &:first-child {
    border-top: 0;
  }
  &:hover {
    background: rgba(255, 255, 255, 0.03);
  }
  .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    flex: none;
  }
  .bd {
    flex: 1;
    min-width: 0;
  }
  .nm {
    font-size: 13px;
    font-weight: 600;
    color: var(--ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .why {
    font-size: 11.5px;
    color: var(--muted);
    margin-top: 2px;
  }
  .val {
    font-family: var(--font-num);
    font-variant-numeric: tabular-nums;
    font-weight: 700;
    font-size: 16px;
    flex: none;
  }
`;

interface Props {
  day: number;
  lang: string;
  onSelect: (h: Hotspot) => void;
}

const Hotspots: React.FC<Props> = ({ day, lang, onSelect }) => {
  const { t } = useTranslation();
  const hotspots = topHotspots(day, 6);
  return (
    <List>
      {hotspots.map((h) => {
        const meta = RISK_TIER_MAP[h.tier];
        const value = Math.round(h.risk * INDEX_SCALE);
        const rate = Math.round((nodeRiskAt(h.site.id, day) - nodeRiskAt(h.site.id, day - 1)) * INDEX_SCALE);
        const tierLabel = t(`fc.tier.${h.tier}`, { defaultValue: h.tier });
        const why =
          rate > 0
            ? t("hot.rising", { tier: tierLabel, n: rate, defaultValue: "{{tier}}, rising {{n}} pts a day" })
            : rate < 0
              ? t("hot.easing", { tier: tierLabel, n: Math.abs(rate), defaultValue: "{{tier}}, easing {{n}} pts a day" })
              : t("hot.steady", { tier: tierLabel, defaultValue: "{{tier}}, steady" });
        return (
          <Row key={h.site.id} onClick={() => onSelect(h)}>
            <span className="dot" style={{ background: meta.color }} />
            <span className="bd">
              <div className="nm">{lang === "ar" ? h.site.nameAr : h.site.name}</div>
              <div className="why">{why}</div>
            </span>
            <span className="val" style={{ color: meta.color }}>{value}</span>
          </Row>
        );
      })}
    </List>
  );
};

export default Hotspots;
