/**
 * Dubai site network - the nodes the model, flows and nudges operate on.
 * Coordinates are approximate, OSM-verified public landmarks (no clinical-study
 * or private sites). Screening kiosks are generic Illustrative points.
 *
 * footfall / population are 0..1 relative weights. seed = initial infected
 * fraction at the start of the observed window (gateways seed the season).
 */

export type SiteType =
  | "gateway"
  | "mall"
  | "oldcity"
  | "transit"
  | "hospital"
  | "clinic"
  | "pharmacy"
  | "education"
  | "residential"
  | "hotel"
  | "mosque"
  | "venue"
  | "kiosk";

export interface Site {
  id: string;
  name: string;
  nameAr: string;
  type: SiteType;
  lat: number;
  lon: number;
  footfall: number;
  population: number;
  seed: number;
}

