/**
 * Single source of truth for the headline KPIs so the Map rail, Summary page and
 * Insights page can never report different numbers for the same metric.
 */
import {
  predictedSymptomaticRate,
  peakDay,
  areasAtRisk,
  cityRiskFraction,
  tierForFraction,
  RiskTier,
  RISK_TIER_MAP,
} from "./forecast";
import { recommendedPlan } from "./scenarios";

export interface Kpis {
  screenings: number;
  symptomatic: number;
  districts: number;
  peak: number;
  averted: number;
  cityTier: RiskTier;
  cityTierColor: string;
}

/** Derive every headline KPI from the live screening count and the timeline day. */
export const deriveKpis = (realScreenings: number, day: number): Kpis => {
  const tier = tierForFraction(cityRiskFraction(day));
  return {
    screenings: realScreenings,
    symptomatic: predictedSymptomaticRate(day),
    districts: areasAtRisk(day),
    peak: peakDay(),
    averted: recommendedPlan().casesAverted,
    cityTier: tier,
    cityTierColor: RISK_TIER_MAP[tier].color,
  };
};
